window.__finlexDocLoaded(10170,{"id":10170,"articles":[{"id":1000711,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Prescribes accounting and disclosure principles for interim periods (quarterly 10-Q reporting), adopting an 'integral' view where each interim period is viewed primarily as an integral part of the annual period.","seq":0},{"id":1000712,"no":"ASC 270-10","heading":"Integral Approach to Interim Periods","text":"• Integral View (ASC 270-10-45-1): Certain annual costs (e.g., property taxes, annual bonuses, volume rebates, LIFO liquidations expected to be replaced by year-end) are allocated/deferred across interim periods.\n• Income Taxes (ASC 740-270): Computed using the estimated Annual Effective Tax Rate (AETR) applied to YTD ordinary income, with discrete items recognized in the quarter incurred.","seq":1},{"id":1000713,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Integral vs. Discrete View: ASC 270 follows an INTEGRAL approach (allowing deferral of certain interim variances/costs expected to reverse by year-end), whereas IAS 34 follows a DISCRETE approach (each interim period stands alone, except for annual effective tax rate).","seq":2},{"id":1000714,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
